func getCoveragePercent(a *types.ConfigAnalysis) int {
	total := a.CriticalCount + a.HighValueCount + a.MediumValueCount + a.OptionalCount
	if total == 0 {
		return 100
	}
	recommended := a.CriticalCount + a.HighValueCount
	return (recommended * 100) / total
}

func getCriticalCount(a *types.ConfigAnalysis) int {
	count := 0
	for _, rec := range a.LinterRecommendations {
		if rec.Priority == 0 {
			count++
		}
	}
	return count
}

func getHighCount(a *types.ConfigAnalysis) int {
	count := 0
	for _, rec := range a.LinterRecommendations {
		if rec.Priority == 1 {
			count++
		}
	}
	return count
}

